LESSONS = [
 dict(id='A01', title='高级测量：用证据决定技术投入', prereq=['I12'], concepts='C32/C19', goal='为一个真实瓶颈设计基线、实验和回归，不为高级而高级。', m=['区分症状、假设、干预和证据。','证明收益没有靠删功能或降低未声明质量获得。'], k=['外部CPU/GPU分析器知道用途与入口。'], stop='没有性能问题可以跳过高级线；不实现Profiler和基准框架。', body=['高级判断不是会念更多优化术语，而是能排除错误归因。记录分辨率、场景、设备、构建版本和样本分布，并重复关键路径。','帧时间改善之外还要看载入、内存、视觉与功能回归。一次实验不确定就标不确定，不能把合成数据当产品跑分。'], initial='合成基线三段路线、一次加载尖峰与稳定样本；优化方案有明确改动清单。', controls='路线、预热、画质基线、单项干预、重复测量次数。', steps=['先写可被否定的瓶颈假设。','选择唯一变量并固定其他条件。','比较慢帧与资源成本，检查功能和视觉是否退化。'], feedback='每个数据点标来源；结论分支持/不支持/证据不足。', failure='故障：优化同时删阴影和NPC，却不在报告披露；要求同功能比较或声明取舍。', reset='回到原构建和条件，保留实验记录。', ui=['常用：分析报告、构建版本和画质开关。','会定位：CPU/GPU时间与加载记录。','按需查：专项分析器操作和引擎后端。'], questions=[('P','只拿最好一次测试能证明稳定收益吗？','不能；要匹配条件并看重复样本和波动。','其他样本去哪了？'),('D','FPS更高但画面缺关键物体，怎样判定？','不算同需求优化；还原或明确变更目标。','需求是否相同？'),('T','新硬件上收益消失，怎么处理？','重新测量瓶颈和条件，不假定优化收益可直接转移。','瓶颈是否改变？'),('K','GPU分析器何时值得查？','现有证据指向图形成本且普通监视不足时。','不是每次都要用。')], remember=['假设要能被验证和否定。','同需求同条件比较。','结论允许证据不足。'], recall=['B14','I07'], practice='后续专项只针对实际目标硬件；先完成实验计划。', sources=['perf']),
 dict(id='A02', title='Shader选修：能控制效果，不必重造渲染器', prereq=['I06'], concepts='C27/C12/C13', goal='定义一个可调卡通明暗或描边效果，并检查边界与成本。', m=['选择一个效果，规定参数、默认值和异常边界。','验收远近、透明、遮挡及目标渲染模式。'], k=['Shader、法线和渲染阶段知道对应问题。'], stop='选修；不把Shader写作变成所有学员毕业门槛，不保证Blender节点原样导入。', body=['卡通明暗分级、描边、手绘贴图不是同一种技术。先明确想改变轮廓、光影还是表面纹理，再决定效果。','AI可写着色器，人要检查参数极值、不同距离和透明交叠；好看的静止样张不代表运动中稳定。'], initial='同一模型普通材质与拟议卡通效果对照；用示意着色而非宣称目标引擎已实现。', controls='明暗层级2/3/4、描边宽0到3像素示意、观察距离、效果开关。', steps=['选一种效果并写不可改变的功能。','从近景切到游戏距离，比较识别与闪烁风险。','把参数调到边界并定义合理限制。'], feedback='标明像素宽或世界宽的定义；效果开关不得改变碰撞。', failure='故障：描边把远处细物体淹没；要求距离和线宽策略，不单纯提高强度。', reset='恢复普通材质、机位和参数。', ui=['常用：暴露的效果参数与对照开关。','会定位：ShaderMaterial和渲染器支持。','按需查：Shader语法、渲染阶段、屏幕纹理。'], questions=[('P','画面有凸起纹理就会改变碰撞吗？','不会自动改变，需分开建几何/物理。','表现与物理是什么关系？'),('D','近看很好远处变黑团，查什么？','描边尺度、距离、细节密度与混叠；用实际镜头测试。','参数以什么单位表示？'),('T','手机渲染模式不支持原效果时怎样取舍？','使用可支持的简化效果或换方案，回到视觉目标而非坚持某算法。','目标还是技术更重要？'),('K','Shader到底解决哪类问题？','定义表面或画面如何计算显示，不等于完整玩法逻辑。','不要求写公式。')], remember=['先说视觉目标再选技术。','效果必须在游戏距离验证。','AI写代码，人定边界。'], recall=['B08','I06'], practice='真实Shader实现留后续素材/工程阶段。', sources=['gltf','pbr','perf']),
 dict(id='A03', title='复杂旋转选修：轨迹对，比公式背得熟重要', prereq=['I04','B01B'], concepts='C28/C03', goal='识别跨角度边界和父级旋转的错误插值。', m=['规定旋转方向、路径和终态。','检查跨±180度与父级变化下的结果。'], k=['Quaternion/Basis是旋转表示工具，API按需查。'], stop='不考展开式、矩阵乘法和插值算法实现。', body=['角度数值接近边界时，直接线性插值可能沿意外长路径走。最短路径也不是所有艺术需求：风车可能希望持续同方向转。','先定义期望路径和参考空间，AI再选表示和实现。可视化坐标与轨迹比背公式更能帮助验收。'], initial='箭头姿态从170到-170度；父节点0/90度；固定步长播放。', controls='直接角度/短路径示意、父转角、持续同向需求、单步播放。', steps=['先画箭头预期怎么走。','对照长短路径，判断哪个符合给定需求。','改变父级后再测，分别报告本地与世界效果。'], feedback='每步显示方向与参考轴；不得把所有旋转错误归咎于四元数。', failure='故障：镜头过边界绕大圈；先检查路径约定与表示。', reset='恢复起点与父变换，清空轨迹。', ui=['常用：关键姿态、轨迹与播放速度。','会定位：旋转模式和父级关系。','按需查：slerp、Quaternion和Basis接口。'], questions=[('P','170到-170数值差很大就必须转340度吗？','不一定，方向可能只需跨边界20度；由路径目标决定。','角度是否环绕？'),('D','父节点转了后方向错，先查什么？','目标和实际使用的坐标空间，不先更换全部算法。','相对谁？'),('T','风车要一直顺转，能总用最短路径吗？','不能盲用，需要累计/方向约定符合连续运动。','路径本身是不是需求？'),('K','四元数现在要背吗？','不用，知道适合旋转表示和插值并会查正确接口。','验收标准是轨迹。')], remember=['终点对不代表过程对。','最短路径也要符合需求。','先说明参考空间。'], recall=['B01B'], practice='后续只针对出现的复杂旋转故障提供示例。', sources=['node','anim']),
 dict(id='A04', title='大场景选修：批量、剔除与加载各治什么', prereq=['A01'], concepts='C29/C30', goal='为重复植被场景选择一种有证据支持的优化策略。', m=['按瓶颈区分批量绘制、细节等级、遮挡和加载问题。','验收视角变化与边界经过时的副作用。'], k=['MultiMesh/LOD/Culling/Streaming分别是工具族。'], stop='不要求同时实现四种技术；小场景不强制学习。', body=['批量减少某些提交成本，LOD降低远处细节，剔除减少不需绘制内容，流送管理驻留资源。它们不是同一个万能开关。','把整个森林合成一组可能损害有效剔除；分区和边界移动需要测。具体效果由场景和引擎实现决定。'], initial='合成森林格网，一部分在视野外；显示每格实例与资源驻留的示意数。', controls='全场/分区批量、近远细节、视角移动、边界加载示意。', steps=['先选一个数据支持的瓶颈。','只改一种策略，比较提交/细节/驻留哪类量变化。','走过分区边界，检查跳变、尖峰和缺物体。'], feedback='所有数值标模拟，不伪装真实Draw Call；可视化被剔除格与保留格。', failure='故障：减少提交却让大量不可见对象仍被整批处理；讨论分区并复测。', reset='恢复场景数量、分区和观察路线。', ui=['常用：策略开关、距离范围、分区大小。','会定位：对应性能报告。','按需查：MultiMesh、LOD和异步加载API。'], questions=[('P','批量绘制能自动解决所有内存问题吗？','不能，各策略解决不同成本。','瓶颈是什么？'),('D','边界突然卡顿，只有平均FPS正常，怎样补证据？','记录边界时序、加载与慢帧，区分稳定段和切换段。','哪一时刻发生？'),('T','森林改为室内房间，优化选择一定相同吗？','不一定，遮挡、可见范围和重复性改变，应重新测。','场景结构变了什么？'),('K','Streaming与LOD有何用途区别？','前者关注资源何时驻留/加载，后者关注表现细节层级。','不要把远就不加载当唯一规则。')], remember=['先区分成本类型。','优化要走过边界再测。','不把所有策略一次全上。'], recall=['I07','A01'], practice='工程实现按实际瓶颈追加，不是当前必交内容。', sources=['perf']),
 dict(id='A05', title='多人认识专题：先知道为什么会复杂', prereq=['I12'], concepts='C31', goal='用事件时间线认识权威、延迟和重连；不开展网络实作。', m=[], k=['权威决定谁能确认结果。','延迟、预测、重连会影响不同客户端看到的状态。'], stop='本课为全K选修，不计入单机毕业条件，不要求服务器和同步代码。', body=['两个人同时拾取同一件物品时，两个屏幕都显示成功不意味着系统可以发两份奖励。需要明确结果由谁确认。','网络消息有延迟和顺序问题，重连还要恢复一致状态。这与本地一次性事件有关，但不能简单复制本地脚本就保证正确。'], initial='客户端A/B与权威节点三条时间线，两个同时拾取请求；数值仅教学示意。', controls='延迟0/100/300毫秒示意、重复请求、断线重连；没有真实网络连接。', steps=['观察两人同时请求时可能出现的冲突。','选择谁确认最终结果并说明用途。','回答本项目现在是否需要多人，给出暂缓理由。'], feedback='只要求用途解释，演示可由老师操控；不考编程和详细故障修复。', failure='反例讨论：每个客户端自行增加奖励会出现什么不一致；不要求排错实操。', reset='清空消息时间线与最终奖励。', ui=['无必会实操界面。','知道网络调试信息的用途。','需要网络项目时再查RPC与网络API。'], questions=[('K','谁应确认同一物品最终归属？','需要一个明确权威规则，不由相互独立客户端随意各自确认。','这是概念认识，不要求架构实现。'),('K','为什么延迟值得考虑？','输入到结果确认有时间差，会影响体验与一致性。','看时间线。'),('K','重连为什么不是重新显示画面就够？','还需恢复正确状态，避免重复奖励和过期信息。','状态从哪里来？'),('K','现在做单机收集游戏需要实现这些吗？','不需要；明确后置，不阻塞主线。','需求有没有多人？')], remember=['多人先问谁确认结果。','认识风险不等于现在实现。'], recall=['B10'], practice='没有网络项目和代码任务；全K轻量识别即可。', sources=['resource']),
 dict(id='A06', title='高级专项结业：一个问题，一份可信决策', prereq=['I12'], concepts='C20/C26/C32', goal='只选一个真实专项，提交取舍、证据和回退方式。', m=['定义所选专项的成功条件和不做范围。','用实验证据与回归决定保留或放弃方案。'], k=['未选专项只认识名称，不参加细考。'], stop='没有高级需求可不选；不以会写Shader、联网、流送当通用能力标准。', body=['高级学习围绕具体限制展开。选择Shader、复杂旋转、性能或大场景其中一个，并补齐该专项前置，不能靠堆功能证明高级。','放弃不合适方案也是有效产出，只要有证据说明成本、限制和替代方向。结业记录应让别人能复现，而非只有漂亮截图。'], initial='四张问题卡与一张无需高级技术卡；每张有目标约束但不提供标准方案。', controls='选择专项、填写成功条件、比较候选、证据自检。', steps=['判断是否真的需要高级工具。','选择对应前置课并只验证一个问题。','检查收益、副作用和回退路径，说明保留/放弃原因。'], feedback='对未选专项不出深题；证据缺失明确标待完成。', failure='故障：选了最多功能的方案却没有目标或测试；退回问题定义。', reset='恢复问题卡，不清除已留存证据。', ui=['复用所选专项界面。','会定位：版本、测试与回退。','按需查：具体实现；不增加工具考试。'], questions=[('P','高级阶段必须四种专项全做吗？','不必，围绕实际需求选择并完成前置。','目标是问题解决还是百科？'),('D','只有静态截图但目标是消除运动闪烁，证据够吗？','不够，需相应运动测试和条件。','证据覆盖了成功条件吗？'),('T','方案失败后如何留下长期价值？','记录原因、可复用部分、边界和替代方案，并安全回退。','失败是否可解释？'),('K','没选的技术要考实现吗？','不考，只需知道需要时往哪里查。','学习范围已选择。')], remember=['一个专项解决一个真实问题。','证据要匹配目标。','放弃方案可以是正确判断。'], recall=['B15','I12'], practice='所选A01/A02/A03/A04为条件前置；课堂先完成选择，真正实验在专项就绪后开展。', sources=['perf'])
]
